// @font-face rules for the bundled IBM Plex, shared by every theme's CSS.
const FONT_FACES = "@font-face { font-family: 'Nous Sans'; font-weight: 400 600; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }\n@font-face { font-family: 'Nous Mono'; font-weight: 400; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }\n@font-face { font-family: 'Nous Mono'; font-weight: 500; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }\n@font-face { font-family: 'Nous Mono'; font-weight: 600; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,) format('woff2'); }\n"

const SIDEBAR_ZONE = '[data-tree-group]:has([data-slot="sidebar"])'

// One theme, two palettes: Desktop puts `.dark` on the root in dark mode, so every
// colour the CSS paints is a variable, set once per mode. The art is the same in both.
const modeVars = (sel, V) => `${sel} {
  --nous-ink: ${V.ink};
  --nous-dim: ${V.dim};
  --nous-rule: color-mix(in srgb, ${V.rule} 32%, transparent);
  --nous-glow: ${V.glow};
  --nous-glow2: ${V.glow2};
  /* the neon tube: pink into cyan, the sunset-to-sea of the art */
  --nous-tube: linear-gradient(90deg, transparent, ${V.glow} 18%, ${V.glow2} 82%, transparent);
  --nous-surface: ${V.surface};
  --nous-send: ${V.send};
  --nous-send-ink: ${V.sendInk};
  --nous-wordmark: linear-gradient(180deg, ${V.wordmark.join(', ')});
  --nous-wordmark-shadow: ${V.wordmarkShadow};
}`

function cssFor(THEME) {
  const V = THEME.vars
  const ART = THEME.art
  // Painted art keeps its own antialiasing; dithered art shows one dot per 2 CSS px.
  const IR = THEME.render === 'smooth' ? 'auto' : 'pixelated'
  // Prefix match: picking an accent colour renames the active theme to `<name>-accent-<hex>`.
  const T = `:root[data-hermes-theme^="${THEME.name}"]`

  // A theme's own lettering for the wordmark; a theme without one keeps the app's Collapse.
  const D = THEME.display
  const display = D
    ? `@font-face { font-family: '${D.family}'; font-weight: ${D.weight}; font-style: normal; font-display: block; src: url(${D.src}) format('woff2'); }
${T} .wordmark { font-family: '${D.family}', 'Collapse', var(--font-sans) !important; font-weight: ${D.weight} !important; letter-spacing: ${D.tracking} !important; font-synthesis: none; }
`
    : ''

  return `${FONT_FACES}${display}
${modeVars(T, V)}
${modeVars(`${T}.dark`, { ...V, ...THEME.darkVars })}

${T} {
  --nous-art-floor: 290px;
  /* the collage fills the sidebar's width; painted art stays sharp up to 340px */
  --nous-collage: min(100%, 340px);
}

/* ── Sidebar art ─────────────────────────────────────────────────────────── */

${T} ${SIDEBAR_ZONE} > [data-panel-header] {
  position: relative;
  height: 262px !important;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header]::before {
  content: '';
  position: absolute;
  /* below the title bar row, so the window controls never sit on the art; the
     bottom stays put, so the fade still ends above the tabs */
  inset: 20px 0 18px 0;
  background: url("${ART.top}") center 0 / 320px auto no-repeat;
  image-rendering: ${IR};
  /* the art's flat top edge fades in instead of cutting across the hair */
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 9%, #000 72%, transparent);
  mask-image: linear-gradient(to bottom, transparent, #000 9%, #000 72%, transparent);
  pointer-events: none;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header] > [data-window-drag-handle] {
  z-index: 1;
}

${T} ${SIDEBAR_ZONE} > [data-panel-header] > [data-zone-tabstrip] {
  z-index: 1;
  background: transparent;
  padding-inline: 14px;
  gap: 10px;
  /* inactive tabs fill with this colour: clear it so the art shows through them, as through the active tab */
  --pane-tab-strip-bg: transparent;
}

${T} [data-tree-group]:not(:has([data-slot="sidebar"])) > [data-panel-header] > [data-zone-tabstrip] {
  padding-left: 10px;
}

${T} [data-slot="sidebar"] {
  position: relative;
  isolation: isolate;
}

${T} [data-slot="sidebar"]::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: auto 0 0 0;
  height: var(--nous-art-floor);
  background: url("${ART.bottom}") center bottom / var(--nous-collage) auto no-repeat;
  image-rendering: ${IR};
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 12%);
  mask-image: linear-gradient(to bottom, transparent, #000 12%);
  pointer-events: none;
}

/* the session list stops where the collage starts fading in, and scrolls above it */
${T} [data-slot="sidebar"] [data-slot="sidebar-content"] > *:last-child {
  padding-bottom: var(--nous-art-floor);
}

/* ── Shorter windows: smaller art, never cropped ─────────────────────────── */

/* Below 1080px the full-size art leaves only a handful of sessions on screen, so
   it steps down: the bust to 240px and the collage to 270px, then the collage to
   180px, then the collage goes and the bust drops to 160px. Each step shows the
   whole image, and the header keeps the same 22px under the bust. */
@media (max-height: 1079px) {
  ${T} {
    --nous-art-floor: 230px;
    --nous-collage: min(100%, 270px);
  }

  ${T} ${SIDEBAR_ZONE} > [data-panel-header] {
    height: 202px !important;
  }

  ${T} ${SIDEBAR_ZONE} > [data-panel-header]::before {
    background-size: 240px auto;
    background-position: right top;
  }
}

@media (max-height: 859px) {
  ${T} {
    --nous-art-floor: 155px;
    --nous-collage: min(100%, 180px);
  }
}

@media (max-height: 719px) {
  ${T} {
    --nous-art-floor: 0px;
  }

  ${T} ${SIDEBAR_ZONE} > [data-panel-header] {
    height: 142px !important;
  }

  ${T} ${SIDEBAR_ZONE} > [data-panel-header]::before {
    background-size: 160px auto;
  }
}

/* ── Tabs: mono caps, a lit neon tube under the active one ──────────────── */

${T} [data-slot="pane-tab"],
${T} [data-tree-tab] {
  font-family: var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 0 !important;
  box-shadow: none !important;
}

${T} [data-slot="pane-tab"][data-active="true"],
${T} [data-tree-tab][data-active="true"] {
  color: var(--nous-ink);
  background: transparent !important;
  text-shadow: 0 0 6px color-mix(in srgb, var(--nous-glow) 70%, transparent);
  box-shadow: inset 0 -2px 0 var(--nous-glow), 0 8px 12px -10px var(--nous-glow) !important;
}

${T} [data-slot="pane-tab"][data-active="true"]::after,
${T} [data-tree-tab][data-active="true"]::after {
  display: none !important;
}

${T} [data-slot="pane-tab"][data-active="false"] {
  color: var(--nous-dim);
}

/* ── Neon rules: pink into cyan, fading at both ends ─────────────────────── */

${T} [data-tree-group][data-window-top] > [data-panel-header] {
  border-bottom: 1px solid;
  border-image: var(--nous-tube) 1;
}

${T} [data-slot="sidebar"] {
  border-right: 1px solid !important;
  border-image: linear-gradient(180deg, transparent, var(--nous-glow) 20%, var(--nous-glow2) 80%, transparent) 1 !important;
}

${T} [data-sash-overlap] {
  opacity: 0;
}

${T} [data-slot="composer-surface"] {
  border: 1px solid color-mix(in srgb, var(--nous-glow) 55%, transparent) !important;
  border-radius: 10px !important;
  background: var(--nous-surface) !important;
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--nous-glow2) 14%, transparent),
    0 0 22px -8px var(--nous-glow) !important;
}

${T} [data-slot="composer-surface"]:focus-within {
  border-color: var(--nous-glow) !important;
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--nous-glow2) 28%, transparent),
    0 0 28px -6px var(--nous-glow) !important;
}

${T} [data-slot="kbd"] {
  font-family: var(--font-mono);
  background: transparent !important;
  border: 1px solid color-mix(in srgb, var(--nous-glow2) 60%, transparent) !important;
  color: var(--nous-glow2) !important;
}

${T} [data-slot="sidebar-input"],
${T} [data-slot="sidebar"] input[type="search"] {
  border: 0 !important;
  border-bottom: 1px solid var(--nous-rule) !important;
  border-radius: 0 !important;
  background: transparent !important;
}

/* ── Empty chat: the loading screen above the neon sign ──────────────────── */

${T} [data-slot="aui_intro"] {
  position: relative;
  isolation: isolate;
  overflow: visible;
}

${T} [data-slot="aui_intro"]::before {
  content: '';
  position: absolute;
  z-index: -1;
  left: 50%;
  bottom: calc(100% - 175px);
  width: 900px;
  height: 450px;
  max-width: 100%;
  transform: translateX(-50%);
  background: url("${ART.hero}") center bottom / contain no-repeat;
  image-rendering: ${IR};
  /* the painted figure stops on a straight line; fade it out above the sign */
  -webkit-mask-image: linear-gradient(to bottom, #000 58%, transparent 75%);
  mask-image: linear-gradient(to bottom, #000 58%, transparent 75%);
  pointer-events: none;
}

/* neon horizon lines either side of the sign */
${T} [data-slot="aui_intro"]::after {
  content: '';
  position: absolute;
  z-index: -1;
  left: 4%;
  right: 4%;
  top: 40px;
  height: 120px;
  background:
    var(--nous-tube) left 0 / 100% 1px no-repeat,
    var(--nous-tube) left 100% / 100% 1px no-repeat;
  opacity: 0.7;
  pointer-events: none;
}

${T} .wordmark {
  mix-blend-mode: normal !important;
}

${T} .wordmark > span:not([aria-hidden]) > span {
  color: transparent;
  background: var(--nous-wordmark);
  -webkit-background-clip: text;
  background-clip: text;
  filter:
    drop-shadow(0 0 2px var(--nous-wordmark-shadow))
    drop-shadow(0 0 14px color-mix(in srgb, var(--nous-glow) 45%, transparent));
}

${T} [data-slot="aui_intro"] p:not(.wordmark) {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  letter-spacing: 0.02em;
  line-height: 1.7;
  color: var(--nous-ink);
  max-width: 44ch;
  margin-inline: auto;
}

/* the game touch: a mission card title over the line under the sign */
${T} .wordmark + p::before {
  content: '\\2605  NEW MISSION  \\2605';
  display: block;
  margin-bottom: 0.5em;
  font-size: 0.7rem;
  letter-spacing: 0.32em;
  color: var(--nous-glow2);
  text-shadow: 0 0 8px color-mix(in srgb, var(--nous-glow2) 60%, transparent);
}

/* ── Send button: the one lit button ─────────────────────────────────────── */

${T} [data-slot="composer-surface"] button[data-variant="default"] {
  background: var(--nous-send) !important;
  color: var(--nous-send-ink) !important;
  box-shadow: 0 0 14px -2px var(--nous-send) !important;
}
`
}

const desktopTheme = THEME => ({
  name: THEME.name,
  label: THEME.label,
  description: THEME.description,
  // Light and dark palettes around the same art. A theme without its own dark
  // palette uses one for both; without darkColors at all Desktop would synthesize a light one.
  colors: THEME.colors,
  darkColors: THEME.darkColors ?? THEME.colors,
  typography: THEME.typography,
  terminal: THEME.terminal,
  darkTerminal: THEME.darkTerminal ?? THEME.terminal,
  customCSS: cssFor(THEME)
})

// The terminal skins in cli/skins are named `<plugin id>-<god>`. Hermes shares the
// active skin with Desktop, and Desktop prefers a skin over a plugin theme, so a
// terminal `/skin pantheon-hades` would paint Desktop with the skin's palette
// alone. Whenever that skin becomes the active theme, switch to the god's full
// theme instead. This only changes Desktop's own pick; the terminal keeps its skin.
function followTerminalSkins() {
  const root = document.documentElement
  const gods = new Set(THEMES.map(THEME => THEME.name))
  const prefix = `${PLUGIN.id}-`

  const follow = () => {
    const active = root.dataset.hermesTheme ?? ''
    const god = active.startsWith(prefix) ? active.slice(prefix.length) : ''

    if (gods.has(god)) {
      requestTheme(god)
    }
  }

  const observer = new MutationObserver(follow)
  observer.observe(root, { attributes: true, attributeFilter: ['data-hermes-theme'] })
  follow()

  return () => observer.disconnect()
}

const PLUGIN = {"id": "nous", "name": "Nous"}

export default {
  id: PLUGIN.id,
  name: PLUGIN.name,
  register(ctx) {
    ctx.registerMany(THEMES.map(THEME => ({ id: THEME.name, area: THEMES_AREA, data: desktopTheme(THEME) })))
    ctx.onDispose(followTerminalSkins())
  }
}
